/** Real view/session transfers, classic/flexible snap, closing and process recreation. */
public final class EightImmersiveSmoke extends Instrumentation {
    MainActivity home;View root;DesktopStore store;
    ServerSocket server;volatile boolean serving=true;
    private void choose(EightProfile profile)throws Exception{home=EightShellSwitch.choose(this,home,profile);root=home.getWindow().getDecorView();}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        store=new DesktopStore(getTargetContext());EightDefaults.initialize(store);store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putString("eight_profile","8").commit();
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();waitForIdleSync();
        ui(()->{for(String kind:new String[]{"computer","desktop","documents","downloads","favorites","files","games","links","music","network","pictures","recycle","recycle-full","search","contacts","userfolder","videos"})check(EightIconAssets.resource(kind)!=0,"Supplied icon mapped: "+kind);check(iconHash("recycle")!=iconHash("recycle-full"),"Empty/full Recycle Bin artwork differs");home.open("@browser");});
        server=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));Thread fixture=new Thread(this::serve,"eight-immersive-test-http");fixture.setDaemon(true);fixture.start();
        BrowserPanel browser=find(root,BrowserPanel.class);WebView web=browser.web();ui(()->browser.navigate("http://127.0.0.1:"+server.getLocalPort()+"/fixture"));awaitJs(web,"window.nthState","73");awaitJs(web,"document.readyState","\"complete\"");
        ui(()->{home.openEightTile("@browser");check(apps().visible(),"Start app uses immersive host");check(apps().currentBody()==browser&&browser.web()==web,"Same BrowserPanel and WebView transferred");apps().commands(true);check(description(browser,"Browser address").isShown(),"Immersive bottom address controls reachable");home.open("@start");check(find(root,EightStartScreen.class).isShown()&&!apps().visible(),"Start covers immersive app");home.open("@start");check(apps().visible()&&apps().currentBody()==browser,"Start toggles to prior owned surface");});awaitJs(web,"document.getElementById('draft').value","\"kept\"");
        ui(()->browser.navigate("http://127.0.0.1:"+server.getLocalPort()+"/second"));awaitJs(web,"location.pathname","\"/second\"");awaitJs(web,"document.readyState","\"complete\"");awaitBackHistory(web);ui(()->{check(browser.web()==web,"History belongs to the retained live WebView");apps().commands(false);home.onBackPressed();check(apps().visible(),"Back stays inside the immersive browser while history exists");});awaitJs(web,"location.pathname","\"/fixture\"");shot("eight2-browser-immersive");
        ui(()->{home.open("@browser");check(!apps().owns("@browser")&&browser.isShown()&&browser.web()==web,"Desktop presentation restores same browser session");home.openEightTile("@nota");TenNotaPanel nota=find(root,TenNotaPanel.class);nota.input.setText("Preserve this Nota draft");Object assistant=nota.assistant;home.open("@nota");check(!nota.closed&&nota.assistant==assistant&&nota.input.getText().toString().equals("Preserve this Nota draft"),"Nota transfer does not close its assistant or lose draft");home.openEightTile("@nota");check(!nota.closed&&apps().currentBody()==nota,"Nota can transfer back repeatedly");home.open("@eight-switcher");EightAppSwitcher switcher=find(root,EightAppSwitcher.class);check(switcher.isShown()&&description(switcher,"Switch to Desktop")!=null&&description(switcher,"Switch to Nth Nota")!=null,"Left switcher has one Desktop and real owned apps");description(switcher,"Switch to Desktop").performClick();check(!apps().visible(),"Desktop switch keeps immersive sessions hidden");});shot("eight2-desktop-icons");
        ui(()->{home.openEightTile("@notes");((EditText)description(apps(),"Notepad text")).setText("Immersive note survives recreation");check(!apps().snap("@gadget:calculator"),"Narrow Eight viewport falls back without unusable split");home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);});
        float density=home.getResources().getDisplayMetrics().density;shell("wm size "+Math.round(1100*density)+"x"+Math.round(650*density));awaitWidth(810);
        ui(()->{apps().show("@notes");check(apps().snap("@gadget:calculator"),"Original Eight supports compact owned pair at usable width");});waitForIdleSync();SystemClock.sleep(300);
        ui(()->{EightImmersive.Session right=apps().sessions.get("@gadget:calculator");check(Math.abs(right.pane.getWidth()/home.getResources().getDisplayMetrics().density-320)<3,"Original Eight companion stays 320dp");check(apps().sessions.get("@notes").window.body.isShown()&&right.window.body.isShown(),"Both snapped apps have real interactive bodies");});shot("eight2-classic-snap");
        choose(EightProfile.EIGHT_POINT_ONE);ui(()->{home.open("@settings");check(description(root,"PC settings category PC and devices")!=null&&description(root,"PC settings category Search and apps")!=null,"8.1 settings has its own hierarchy");check(((CheckBox)description(root,"8.1 Update mouse controls and taskbar apps")).isChecked(),"8.1 Update defaults on after shell change");home.openEightTile("@notes");});awaitWidth(810);ui(()->{check(apps().snap("@gadget:calculator"),"8.1 supports flexible pair at "+apps().getWidth()/home.getResources().getDisplayMetrics().density+"dp");apps().ratio=.65f;apps().commands(true);});waitForIdleSync();SystemClock.sleep(300);
        ui(()->{EightImmersive.Session a=apps().sessions.get("@notes"),b=apps().sessions.get("@gadget:calculator");check(a.pane.getWidth()>b.pane.getWidth(),"8.1 ratio moves divider");check(a.pane.getRight()<=b.pane.getLeft(),"Snapped panes do not overlap");home.open("@start");home.open("@start");check(apps().visible()&&apps().secondary!=null,"Start restores snapped pair");});shot("eight2-flexible-snap");
        ui(()->{home.open("@volume");EightCharms charms=find(root,EightCharms.class);check(description(charms,"Music volume") instanceof SeekBar&&apps().visible(),"Volume controls overlay the current immersive surface");charms.show("brightness");check(description(charms,"Brightness") instanceof SeekBar&&apps().visible(),"Brightness controls retain the current app");charms.dismiss();apps().focused="@notes";apps().commands(true);MotionEvent down=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,apps().getWidth()-10,apps().getHeight()-10,0);apps().dispatchTouchEvent(down);down.recycle();MotionEvent cancel=MotionEvent.obtain(0,0,MotionEvent.ACTION_CANCEL,apps().getWidth()-10,apps().getHeight()-10,0);apps().dispatchTouchEvent(cancel);cancel.recycle();check(apps().focused.equals("@notes"),"App command bar does not change the focused pane");});
        ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);ui(()->home.recreate());Activity recreated=monitor.waitForActivityWithTimeout(15000);removeMonitor(monitor);check(recreated instanceof MainActivity,"Activity recreated");home=(MainActivity)recreated;root=home.getWindow().getDecorView();waitForIdleSync();SystemClock.sleep(500);
        ui(()->{check(apps().visible()&&apps().owns("@notes")&&apps().owns("@gadget:calculator"),"Owned pair restored across recreation");check(((EditText)description(apps(),"Notepad text")).getText().toString().equals("Immersive note survives recreation"),"Note text retained");apps().close("@notes");check(!apps().owns("@notes")&&apps().owns("@gadget:calculator"),"Closing one pane retains its companion");home.open("@eight-switcher");description(root,"Switch to Desktop").performClick();home.open("@notes");check(((EditText)description(root,"Notepad text")).getText().toString().equals("Immersive note survives recreation"),"Closed immersive note reopens correctly on Desktop");});
        result.putString("stream","PASS: supplied icon mapping and empty/full artwork; same live browser and WebView across presentations; Nota assistant and draft continuity; left switcher; original 320dp and flexible 8.1 snap; narrow fallback; 8.1 settings/Update option; snapped-pair recreation and independent closing\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable failure){try{shot("eight2-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(failure));finish(Activity.RESULT_CANCELED,result);}finally{serving=false;try{if(server!=null)server.close();shell("wm size reset");}catch(Exception ignored){}}}
    void serve(){while(serving)try(Socket client=server.accept()){client.setSoTimeout(3000);BufferedReader reader=new BufferedReader(new InputStreamReader(client.getInputStream(),StandardCharsets.UTF_8));String line=reader.readLine();if(line==null)continue;while((line=reader.readLine())!=null&&!line.isEmpty()){}byte[] page="<!doctype html><meta name='viewport' content='width=device-width, initial-scale=1'><title>Immersive session</title><body><input id='draft' value='kept'><script>window.nthState=73</script>".getBytes(StandardCharsets.UTF_8);OutputStream out=client.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: "+page.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(page);out.flush();}catch(IOException ignored){}}
    EightImmersive apps(){return find(root,EightImmersive.class);}
    void ui(Runnable action)throws Exception{FutureTask<Void> task=new FutureTask<>(action,null);home.runOnUiThread(task);task.get(20,TimeUnit.SECONDS);waitForIdleSync();}
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void shell(String command)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){while(in.read()!=-1){}}}
    void awaitWidth(int dp)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(apps().getWidth()/home.getResources().getDisplayMetrics().density<dp&&SystemClock.uptimeMillis()<end){SystemClock.sleep(100);waitForIdleSync();}check(apps().getWidth()/home.getResources().getDisplayMetrics().density>=dp,"Wide test viewport available: "+apps().getWidth()/home.getResources().getDisplayMetrics().density+"dp");}
    void awaitJs(WebView web,String query,String expected)throws Exception{long end=SystemClock.uptimeMillis()+10000;String[] value={null};while(SystemClock.uptimeMillis()<end){CountDownLatch latch=new CountDownLatch(1);home.runOnUiThread(()->web.evaluateJavascript(query,r->{value[0]=r;latch.countDown();}));latch.await(3,TimeUnit.SECONDS);if(expected.equals(value[0]))return;SystemClock.sleep(150);}throw new AssertionError("Browser state: "+query+" = "+value[0]);}
    void awaitBackHistory(WebView web)throws Exception{long end=SystemClock.uptimeMillis()+10000;boolean[] committed={false};while(SystemClock.uptimeMillis()<end){ui(()->{android.webkit.WebBackForwardList history=web.copyBackForwardList();int at=history.getCurrentIndex();committed[0]=web.canGoBack()&&at>0&&history.getItemAtIndex(at-1).getUrl().endsWith("/fixture");});if(committed[0])return;SystemClock.sleep(100);}throw new AssertionError("HTTP navigation has no committed fixture back entry");}
    int iconHash(String kind){Bitmap image=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);Drawable icon=EightIconAssets.drawable(home,kind);icon.setBounds(0,0,64,64);icon.draw(new Canvas(image));int[] pixels=new int[4096];image.getPixels(pixels,0,64,0,0,64,64);int hash=java.util.Arrays.hashCode(pixels);image.recycle();return hash;}
    void shot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(200);Bitmap image=getUiAutomation().takeScreenshot();boolean black=image==null;if(image!=null){black=true;for(int y=0;y<image.getHeight()&&black;y+=24)for(int x=0;x<image.getWidth();x+=24)if((image.getPixel(x,y)&0xffffff)!=0){black=false;break;}}if(black){if(image!=null)image.recycle();image=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);Bitmap target=image;ui(()->root.draw(new Canvas(target)));name+="-view";}try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}
    static <T extends View>T find(View view,Class<T> type){return EightSmoke.find(view,type);}
    static View description(View view,String value){return EightSmoke.description(view,value);}
}
